class Solution:
    def isOneEditDistance(self, s: str, t: str) -> bool:
        if len(s) > len(t):
            s, t = t, s
        if len(t) - len(s) > 1:
            return False
        for i, (a, b) in enumerate(zip(s, t)):
            if a != b:
                return s[i+1:] == t[i+1:] if len(s) == len(t) else s[i:] == t[i+1:]
        return len(t) == len(s) + 1

class Solution {
    public boolean isOneEditDistance(String s, String t) {
        if (s.length() > t.length()) { String x = s; s = t; t = x; }
        if (t.length() - s.length() > 1) return false;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != t.charAt(i))
                return s.length() == t.length() ? s.substring(i + 1).equals(t.substring(i + 1)) : s.substring(i).equals(t.substring(i + 1));
        }
        return t.length() == s.length() + 1;
    }
}

