class Solution:
    def maximumGap(self, nums: List[int]) -> int:
        if len(nums) < 2:
            return 0
        lo, hi = min(nums), max(nums)
        if lo == hi:
            return 0
        n = len(nums)
        size = max(1, (hi - lo + n - 2) // (n - 1))
        count = (hi - lo) // size + 1
        mins = [float('inf')] * count
        maxs = [float('-inf')] * count
        used = [False] * count
        for x in nums:
            i = (x - lo) // size
            mins[i] = min(mins[i], x); maxs[i] = max(maxs[i], x); used[i] = True
        ans, prev = 0, lo
        for i in range(count):
            if used[i]:
                ans = max(ans, int(mins[i] - prev)); prev = maxs[i]
        return ans

class Solution {
    public int maximumGap(int[] nums) {
        if (nums.length < 2) return 0;
        int lo = nums[0], hi = nums[0];
        for (int x : nums) { lo = Math.min(lo, x); hi = Math.max(hi, x); }
        if (lo == hi) return 0;
        int n = nums.length;
        long size = Math.max(1L, ((long) hi - lo + n - 2) / (n - 1));
        int count = (int) (((long) hi - lo) / size + 1);
        int[] mins = new int[count], maxs = new int[count]; boolean[] used = new boolean[count];
        Arrays.fill(mins, Integer.MAX_VALUE); Arrays.fill(maxs, Integer.MIN_VALUE);
        for (int x : nums) { int i = (int) (((long) x - lo) / size); mins[i] = Math.min(mins[i], x); maxs[i] = Math.max(maxs[i], x); used[i] = true; }
        int ans = 0, prev = lo;
        for (int i = 0; i < count; i++) if (used[i]) { ans = Math.max(ans, mins[i] - prev); prev = maxs[i]; }
        return ans;
    }
}

class Solution:
    def compareVersion(self, version1: str, version2: str) -> int:
        a, b = version1.split('.'), version2.split('.')
        for i in range(max(len(a), len(b))):
            x = int(a[i]) if i < len(a) else 0
            y = int(b[i]) if i < len(b) else 0
            if x != y:
                return 1 if x > y else -1
        return 0

class Solution {
    public int compareVersion(String version1, String version2) {
        String[] a = version1.split("\\."), b = version2.split("\\.");
        int n = Math.max(a.length, b.length);
        for (int i = 0; i < n; i++) {
            long x = i < a.length ? Long.parseLong(a[i]) : 0L;
            long y = i < b.length ? Long.parseLong(b[i]) : 0L;
            if (x != y) return x > y ? 1 : -1;
        }
        return 0;
    }
}

class Solution:
    def fractionToDecimal(self, numerator: int, denominator: int) -> str:
        if numerator == 0:
            return "0"
        sign = "-" if (numerator < 0) != (denominator < 0) else ""
        a, b = abs(numerator), abs(denominator)
        whole, rem = divmod(a, b)
        if rem == 0:
            return sign + str(whole)
        out, seen = [], {}
        while rem and rem not in seen:
            seen[rem] = len(out)
            rem *= 10
            digit, rem = divmod(rem, b)
            out.append(str(digit))
        if rem:
            i = seen[rem]
            out.insert(i, "("); out.append(")")
        return sign + str(whole) + "." + "".join(out)

class Solution {
    public String fractionToDecimal(int numerator, int denominator) {
        if (numerator == 0) return "0";
        String sign = ((numerator < 0) ^ (denominator < 0)) ? "-" : "";
        long a = Math.abs((long) numerator), b = Math.abs((long) denominator);
        StringBuilder out = new StringBuilder(sign).append(a / b);
        long rem = a % b;
        if (rem == 0) return out.toString();
        out.append('.'); Map<Long, Integer> seen = new HashMap<>();
        while (rem != 0 && !seen.containsKey(rem)) {
            seen.put(rem, out.length()); rem *= 10; out.append(rem / b); rem %= b;
        }
        if (rem != 0) out.insert(seen.get(rem).intValue(), "(").append(')');
        return out.toString();
    }
}

